"""Hardcoded map data for known official maps.

Key: (w, h, core_a_x, core_a_y)
Value: (encoded_tiles_b64, core_b)
Tiles: 4 tiles packed per byte (2 bits each), base64 encoded.
Tile values: 0=empty, 1=wall, 2=ore_ti, 3=ore_ax
"""

import base64

from cambc import Environment

__all__ = ["MAPS", "decode"]


_TILE_TO_ENV: dict[int, Environment] = {
    0: Environment.EMPTY,
    1: Environment.WALL,
    2: Environment.ORE_TITANIUM,
    3: Environment.ORE_AXIONITE,
}


def _encode(tiles: list[int]) -> str:
    packed = bytearray()
    for i in range(0, len(tiles), 4):
        b = 0
        for j in range(4):
            if i + j < len(tiles):
                b |= (tiles[i + j] & 3) << (j * 2)
        packed.append(b)
    return base64.b64encode(bytes(packed)).decode("ascii")


def decode(data: str, n: int) -> list[Environment]:
    packed = base64.b64decode(data)
    tiles: list[Environment] = []
    for b in packed:
        for j in range(4):
            if len(tiles) >= n:
                break
            tiles.append(_TILE_TO_ENV[(b >> (j * 2)) & 3])
    return tiles


